CREATE TABLE public.invitations (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), email text NOT NULL UNIQUE CHECK (email = lower(email)), token text NOT NULL UNIQUE DEFAULT encode(gen_random_bytes(32),'hex'), billetweb_ref text, created_at timestamptz NOT NULL DEFAULT now(), used_at timestamptz, claim_id uuid, claimed_at timestamptz);
GRANT ALL ON public.invitations TO service_role;
ALTER TABLE public.invitations ENABLE ROW LEVEL SECURITY;
CREATE TABLE public.profiles (user_id uuid PRIMARY KEY REFERENCES auth.users(id) ON DELETE CASCADE, email text NOT NULL, first_name text NOT NULL DEFAULT '', last_name text NOT NULL DEFAULT '', linkedin_url text NOT NULL DEFAULT '', photo_url text, job_title text, company text, company_size text CHECK(company_size IN ('tpe','pme','eti','grand_groupe')), sector text, job_tags text[] NOT NULL DEFAULT '{}', intentions text[] NOT NULL DEFAULT '{}', pitch text CHECK(char_length(pitch)<=160), ai_level text CHECK(ai_level IN ('debutant','praticien','expert')), consent_at timestamptz, lang text NOT NULL DEFAULT 'fr' CHECK(lang IN ('fr','en')), created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), CHECK(job_tags <@ ARRAY['general_management','business_sales','marketing_communication','product_design','tech_data','hr_training','operations_finance','consulting_freelance','student_research']::text[]), CHECK(intentions <@ ARRAY['recruit','find_job','find_clients','find_provider','partner','raise_funds','invest','find_cofounder','share_experience','meet_enthusiasts']::text[]));
GRANT SELECT ON public.profiles TO authenticated;
GRANT UPDATE(first_name,last_name,linkedin_url,photo_url,job_title,company,company_size,sector,job_tags,intentions,pitch,ai_level,lang) ON public.profiles TO authenticated;
GRANT ALL ON public.profiles TO service_role;
ALTER TABLE public.profiles ENABLE ROW LEVEL SECURITY;
CREATE TABLE public.profile_status (user_id uuid PRIMARY KEY REFERENCES public.profiles(user_id) ON DELETE CASCADE, is_speaker boolean NOT NULL DEFAULT false, speaker_id text, sponsor_id text, sponsor_tier text CHECK(sponsor_tier IN ('platinum','gold','silver')), is_admin boolean NOT NULL DEFAULT false, suspended boolean NOT NULL DEFAULT false, manual_override boolean NOT NULL DEFAULT false);
GRANT SELECT ON public.profile_status TO authenticated;
GRANT ALL ON public.profile_status TO service_role;
ALTER TABLE public.profile_status ENABLE ROW LEVEL SECURITY;
CREATE TABLE public.user_roles (user_id uuid REFERENCES auth.users(id) ON DELETE CASCADE, role text NOT NULL CHECK(role='admin'), PRIMARY KEY(user_id,role));
GRANT SELECT ON public.user_roles TO authenticated;
GRANT ALL ON public.user_roles TO service_role;
ALTER TABLE public.user_roles ENABLE ROW LEVEL SECURITY;
CREATE TABLE public.sponsor_domains (domain text PRIMARY KEY CHECK(domain=lower(domain)), sponsor_id text NOT NULL, tier text NOT NULL CHECK(tier IN ('platinum','gold','silver')));
GRANT ALL ON public.sponsor_domains TO service_role;
ALTER TABLE public.sponsor_domains ENABLE ROW LEVEL SECURITY;
CREATE TABLE public.blocks (blocker_id uuid NOT NULL REFERENCES public.profiles(user_id) ON DELETE CASCADE, blocked_id uuid NOT NULL REFERENCES public.profiles(user_id) ON DELETE CASCADE, created_at timestamptz NOT NULL DEFAULT now(), PRIMARY KEY(blocker_id,blocked_id), CHECK(blocker_id<>blocked_id));
GRANT SELECT,INSERT,DELETE ON public.blocks TO authenticated;
GRANT ALL ON public.blocks TO service_role;
ALTER TABLE public.blocks ENABLE ROW LEVEL SECURITY;
CREATE TABLE public.reports (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), reporter_id uuid NOT NULL REFERENCES public.profiles(user_id) ON DELETE CASCADE, reported_id uuid NOT NULL REFERENCES public.profiles(user_id) ON DELETE CASCADE, reason text NOT NULL CHECK(char_length(reason) BETWEEN 1 AND 2000), created_at timestamptz NOT NULL DEFAULT now(), handled_at timestamptz, CHECK(reporter_id<>reported_id));
GRANT SELECT ON public.reports TO authenticated;
GRANT INSERT(reporter_id,reported_id,reason) ON public.reports TO authenticated;
GRANT ALL ON public.reports TO service_role;
ALTER TABLE public.reports ENABLE ROW LEVEL SECURITY;
CREATE FUNCTION public.is_active_member(uid uuid) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT EXISTS(SELECT 1 FROM public.profiles p JOIN public.profile_status s ON s.user_id=p.user_id WHERE p.user_id=uid AND p.consent_at IS NOT NULL AND NOT s.suspended) $$;
CREATE FUNCTION public.can_view_profile(target uuid) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT target=auth.uid() OR (public.is_active_member(auth.uid()) AND public.is_active_member(target) AND NOT EXISTS(SELECT 1 FROM public.blocks WHERE (blocker_id=auth.uid() AND blocked_id=target) OR (blocker_id=target AND blocked_id=auth.uid()))) $$;
REVOKE ALL ON FUNCTION public.is_active_member(uuid),public.can_view_profile(uuid) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.is_active_member(uuid),public.can_view_profile(uuid) TO authenticated,service_role;
CREATE POLICY profiles_read ON public.profiles FOR SELECT TO authenticated USING(public.can_view_profile(user_id));
CREATE POLICY profiles_update ON public.profiles FOR UPDATE TO authenticated USING(user_id=auth.uid()) WITH CHECK(user_id=auth.uid());
CREATE POLICY status_read ON public.profile_status FOR SELECT TO authenticated USING(public.can_view_profile(user_id));
CREATE POLICY roles_read ON public.user_roles FOR SELECT TO authenticated USING(user_id=auth.uid());
CREATE POLICY blocks_read ON public.blocks FOR SELECT TO authenticated USING(blocker_id=auth.uid());
CREATE POLICY blocks_create ON public.blocks FOR INSERT TO authenticated WITH CHECK(blocker_id=auth.uid() AND public.is_active_member(auth.uid()) AND public.can_view_profile(blocked_id));
CREATE POLICY blocks_delete ON public.blocks FOR DELETE TO authenticated USING(blocker_id=auth.uid());
CREATE POLICY reports_read ON public.reports FOR SELECT TO authenticated USING(reporter_id=auth.uid());
CREATE POLICY reports_create ON public.reports FOR INSERT TO authenticated WITH CHECK(reporter_id=auth.uid() AND public.is_active_member(auth.uid()) AND public.can_view_profile(reported_id));
CREATE FUNCTION public.create_member_shell() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN INSERT INTO public.profiles(user_id,email) VALUES(NEW.id,lower(NEW.email)); INSERT INTO public.profile_status(user_id) VALUES(NEW.id); RETURN NEW; END $$;
CREATE TRIGGER phase2_auth_profile AFTER INSERT ON auth.users FOR EACH ROW EXECUTE FUNCTION public.create_member_shell();
CREATE FUNCTION public.touch_profile() RETURNS trigger LANGUAGE plpgsql SET search_path=public AS $$ BEGIN NEW.updated_at=now(); IF OLD.consent_at IS NOT NULL AND (NEW.first_name='' OR NEW.last_name='' OR cardinality(NEW.job_tags)=0 OR cardinality(NEW.intentions)=0 OR NEW.linkedin_url !~* '^https://(www\.)?linkedin\.com/in/[^/?#]+/?$') THEN RAISE EXCEPTION 'Invalid completed profile'; END IF; RETURN NEW; END $$;
CREATE TRIGGER profiles_updated BEFORE UPDATE ON public.profiles FOR EACH ROW EXECUTE FUNCTION public.touch_profile();
CREATE FUNCTION public.claim_invitation(invite_token text, claim uuid) RETURNS text LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE result text; BEGIN UPDATE public.invitations SET claim_id=claim, claimed_at=now() WHERE token=invite_token AND used_at IS NULL AND (claimed_at IS NULL OR claimed_at < now()-interval '10 minutes') RETURNING email INTO result; RETURN result; END $$;
REVOKE ALL ON FUNCTION public.claim_invitation(text,uuid) FROM PUBLIC,anon,authenticated;
GRANT EXECUTE ON FUNCTION public.claim_invitation(text,uuid) TO service_role;
CREATE FUNCTION public.complete_invitation(invite_token text, claim uuid, uid uuid, fields jsonb) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN PERFORM 1 FROM public.invitations WHERE token=invite_token AND claim_id=claim AND used_at IS NULL FOR UPDATE; IF NOT FOUND THEN RAISE EXCEPTION 'Invalid invitation'; END IF; UPDATE public.profiles SET email=fields->>'email',first_name=fields->>'first_name',last_name=fields->>'last_name',linkedin_url=fields->>'linkedin_url',job_title=fields->>'job_title',company=fields->>'company',company_size=fields->>'company_size',sector=fields->>'sector',job_tags=ARRAY(SELECT jsonb_array_elements_text(fields->'job_tags')),intentions=ARRAY(SELECT jsonb_array_elements_text(fields->'intentions')),pitch=fields->>'pitch',ai_level=fields->>'ai_level',lang=fields->>'lang',consent_at=now() WHERE user_id=uid; IF NOT FOUND THEN RAISE EXCEPTION 'Missing profile'; END IF; UPDATE public.invitations SET used_at=now(),claim_id=NULL,claimed_at=NULL WHERE token=invite_token; END $$;
REVOKE ALL ON FUNCTION public.complete_invitation(text,uuid,uuid,jsonb) FROM PUBLIC,anon,authenticated;
GRANT EXECUTE ON FUNCTION public.complete_invitation(text,uuid,uuid,jsonb) TO service_role;
CREATE INDEX profiles_name_idx ON public.profiles(last_name,first_name);
CREATE INDEX blocks_reverse_idx ON public.blocks(blocked_id,blocker_id);
CREATE POLICY avatar_read ON storage.objects FOR SELECT TO authenticated USING(bucket_id='avatars' AND public.can_view_profile((storage.foldername(name))[1]::uuid));
CREATE POLICY avatar_insert ON storage.objects FOR INSERT TO authenticated WITH CHECK(bucket_id='avatars' AND name=auth.uid()::text||'/avatar.jpg');
CREATE POLICY avatar_update ON storage.objects FOR UPDATE TO authenticated USING(bucket_id='avatars' AND name=auth.uid()::text||'/avatar.jpg') WITH CHECK(bucket_id='avatars' AND name=auth.uid()::text||'/avatar.jpg');
CREATE POLICY avatar_delete ON storage.objects FOR DELETE TO authenticated USING(bucket_id='avatars' AND name=auth.uid()::text||'/avatar.jpg');